ValidationRule.errorConditionFormula:
/* If the BypassAcountValidation checbox wasn't changed and this Account is not the top parent account in the hierarchy and the record type, type or support rep was changed, show error*/

AND(
    NOT( ISCHANGED( BypassAccountValidation__c )),
    NOT( ISBLANK( ParentId )),
    OR(
        ISCHANGED( RecordTypeId ),
        ISCHANGED( Type ),
        ISCHANGED(  Support_Rep__c )
    )
)
